// WebhookConfig represents the webhook configuration.
type WebhookConfig struct {
	WebhookURL string `json:"webhook_url"`
}

// webhookStore is an in-memory store for the webhook configuration.
var webhookStore *WebhookConfig

// ConfigureWebhook handles POST requests to configure a webhook URL.
// It validates the URL by sending a GET test request with a 3-second timeout,
// then saves the configuration and returns the result as JSON.
func ConfigureWebhook(ctx *fiber.Ctx) error {
	var config WebhookConfig

	if err := ctx.BodyParser(&config); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "Invalid request body: " + err.Error(),
		})
	}

	if config.WebhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "webhook_url is required",
		})
	}

	// Validate the webhook URL by sending a test GET request with a 3-second timeout.
	client := &http.Client{
		Timeout: 3 * time.Second,
	}

	resp, err := client.Get(config.WebhookURL)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   fmt.Sprintf("Failed to reach webhook URL: %v", err),
		})
	}
	defer resp.Body.Close()

	if resp.StatusCode >= 400 {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   fmt.Sprintf("Webhook URL returned non-success status: %d", resp.StatusCode),
		})
	}

	// Save the configuration (in-memory for this example).
	webhookStore = &config

	return ctx.Status(fiber.StatusOK).JSON(fiber.Map{
		"success":    true,
		"message":    "Webhook configured successfully",
		"webhook_url": config.WebhookURL,
	})
}

func main() {
	app := fiber.New()

	app.Post("/configure-webhook", ConfigureWebhook)

	// Optional: endpoint to check current configuration.
	app.Get("/webhook-config", func(c *fiber.Ctx) error {
		if webhookStore == nil {
			return c.Status(fiber.StatusNotFound).JSON(fiber.Map{
				"success": false,
				"error":   "No webhook configured",
			})
		}
		return c.JSON(webhookStore)
	})

	// Marshal the webhookStore to JSON for demonstration purposes.
	_, _ = json.Marshal(webhookStore)

	fmt.Println("Server starting on :3000")
	if err := app.Listen(":3000"); err != nil {
		panic(err)
	}
}

