package main

import (
	"encoding/json"
	"net/http"
	"time"

	"github.com/gofiber/fiber/v2"
)

// WebhookConfig represents the webhook configuration
type WebhookConfig struct {
	WebhookURL string `json:"webhook_url"`
}

// ConfigResponse represents the response for webhook configuration
type ConfigResponse struct {
	Success bool   `json:"success"`
	Message string `json:"message"`
}

func main() {
	app := fiber.New()

	app.Post("/configure-webhook", ConfigureWebhook)

	app.Listen(":3000")
}

// ConfigureWebhook handles the webhook configuration
func ConfigureWebhook(ctx *fiber.Ctx) error {
	var config WebhookConfig

	// Parse the JSON body
	if err := ctx.BodyParser(&config); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(ConfigResponse{
			Success: false,
			Message: "Invalid request body: " + err.Error(),
		})
	}

	// Validate that webhook_url is not empty
	if config.WebhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(ConfigResponse{
			Success: false,
			Message: "webhook_url is required",
		})
	}

	// Send a test GET request to the webhook URL with a 3-second timeout
	client := &http.Client{
		Timeout: 3 * time.Second,
	}

	resp, err := client.Get(config.WebhookURL)
	if err != nil {
		return ctx.Status(fiber.StatusOK).JSON(ConfigResponse{
			Success: false,
			Message: "Failed to reach webhook URL: " + err.Error(),
		})
	}
	defer resp.Body.Close()

	// Check if the response status code indicates success (2xx)
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return ctx.Status(fiber.StatusOK).JSON(ConfigResponse{
			Success: false,
			Message: "Webhook URL returned non-success status code: " + resp.Status,
		})
	}

	// Save the configuration (simulated here; in production, persist to a database or config store)
	// For demonstration purposes, we'll just log it or store it in memory
	savedConfig := config

	// Return success response with the saved configuration
	responseData := map[string]interface{}{
		"success": true,
		"message": "Webhook configured successfully",
		"config":  savedConfig,
	}

	jsonBytes, err := json.Marshal(responseData)
	if err != nil {
		return ctx.Status(fiber.StatusInternalServerError).JSON(ConfigResponse{
			Success: false,
			Message: "Failed to marshal response",
		})
	}

	ctx.Set("Content-Type", "application/json")
	return ctx.Status(fiber.StatusOK).Send(jsonBytes)
}

