	app := fiber.New()

	app.Post("/configure-webhook", ConfigureWebhook)

	// Optional: endpoint to retrieve saved configuration
	app.Get("/webhook-config", func(c *fiber.Ctx) error {
		return c.JSON(savedConfig)
	})

	app.Listen(":3000")
}

