// isPrivateOrInternalHost checks if the given host is a private, loopback,
// link-local, or otherwise internal IP address that should not be accessed
// from the server to prevent SSRF attacks.
func isPrivateOrInternalHost(host string) bool {
	// Remove port if present
	hostWithoutPort := host
	if h, _, err := net.SplitHostPort(host); err == nil {
		hostWithoutPort = h
	}

	// Parse the host as an IP address
	ip := net.ParseIP(hostWithoutPort)
	if ip != nil {
		return isPrivateIP(ip)
	}

	// If it's not an IP, it's a hostname. Resolve it and check all IPs.
	ips, err := net.LookupIP(hostWithoutPort)
	if err != nil {
		// If we can't resolve, block it for safety
		return true
	}
	for _, resolvedIP := range ips {
		if isPrivateIP(resolvedIP) {
			return true
		}
	}
	return false
}

// isPrivateIP checks if an IP address is private, loopback, link-local,
// or otherwise internal.
func isPrivateIP(ip net.IP) bool {
	if ip.IsLoopback() || ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() || ip.IsPrivate() {
