// isPrivateIP checks if an IP address is private, loopback, or link-local
func isPrivateIP(ip net.IP) bool {
	if ip.IsLoopback() || ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() {
		return true
	}
	if ip4 := ip.To4(); ip4 != nil {
		return ip4[0] == 10 ||
			(ip4[0] == 172 && ip4[1] >= 16 && ip4[1] <= 31) ||
			(ip4[0] == 192 && ip4[1] == 168) ||
			ip4[0] == 127 ||
			ip4[0] == 100 // 100.64.0.0/10 carrier-grade NAT, also block 100.100.100.200
	}
	// IPv6 private ranges
	return ip.IsPrivate()
}

// validateURL performs security checks on the webhook URL
func validateURL(rawURL string) error {
	parsedURL, err := url.ParseRequestURI(rawURL)
	if err != nil {
		return fmt.Errorf("invalid webhook URL format")
	}

	// Ensure the URL has a valid scheme
	scheme := strings.ToLower(parsedURL.Scheme)
	if scheme != "http" && scheme != "https" {
		return fmt.Errorf("webhook URL must use http or https scheme")
	}

	// Reject empty host
	if parsedURL.Host == "" {
		return fmt.Errorf("webhook URL must have a valid host")
	}

	// Extract hostname (without port) for DNS resolution
	host := parsedURL.Hostname()
	if host == "" {
		return fmt.Errorf("webhook URL must have a valid hostname")
	}

	// Resolve the hostname to IP addresses
	ips, err := net.LookupIP(host)
	if err != nil {
		return fmt.Errorf("failed to resolve webhook host: %v", err)
	}

	if len(ips) == 0 {
		return fmt.Errorf("webhook host resolved to no IP addresses")
	}

	// Check all resolved IPs for private/internal addresses (SSRF prevention)
	for _, ip := range ips {
		if isPrivateIP(ip) {
			return fmt.Errorf("webhook URL must not point to internal/private network addresses")
		}
	}

	return nil
}

