		"192.168.0.0/16",
		"169.254.0.0/16", // link-local
		"0.0.0.0/8",      // current network
	}

	for _, block := range privateIPv4Blocks {
		_, cidr, err := net.ParseCIDR(block)
		if err != nil {
			continue
		}
		if cidr.Contains(ip) {
			return true
		}
	}

	// Check for private IPv6 ranges
	if ip.To4() == nil {
		// IPv6 loopback
		if ip.Equal(net.ParseIP("::1")) {
			return true
		}
		// IPv6 link-local
		if strings.HasPrefix(ip.String(), "fe80:") {
			return true
		}
		// IPv6 unique local addresses
		if strings.HasPrefix(ip.String(), "fc") || strings.HasPrefix(ip.String(), "fd") {
			return true
		}
	}

	return false
}

// validateURL performs comprehensive URL validation to prevent SSRF attacks
func validateURL(rawURL string) (*url.URL, error) {
	// Parse the URL
	parsedURL, err := url.ParseRequestURI(rawURL)
	if err != nil {
		return nil, fmt.Errorf("invalid URL format: %w", err)
	}

	// Ensure the URL has a valid scheme
	scheme := strings.ToLower(parsedURL.Scheme)
	if scheme != "http" && scheme != "https" {
		return nil, fmt.Errorf("webhook URL must use http or https scheme")
	}

	// Ensure the URL has a host
	if parsedURL.Host == "" {
		return nil, fmt.Errorf("webhook URL must include a host")
	}

	// Resolve the hostname to check for private IPs
	host := parsedURL.Hostname()

	// Check if the host is an IP address directly
	if ip := net.ParseIP(host); ip != nil {
		if isPrivateIP(host) {
			return nil, fmt.Errorf("webhook URL must not point to internal/private addresses")
		}
	} else {
		// Resolve DNS to check for private IPs
		ips, err := net.LookupIP(host)
		if err != nil {
			return nil, fmt.Errorf("failed to resolve webhook host: %w", err)
		}

		if len(ips) == 0 {
			return nil, fmt.Errorf("webhook host could not be resolved")
		}

		// Check all resolved IPs for private addresses
		for _, ip := range ips {
			if isPrivateIP(ip.String()) {
				return nil, fmt.Errorf("webhook URL must not point to internal/private addresses")
			}
		}
	}

	// Prevent URL redirection tricks (e.g., using @ to specify credentials)
	if parsedURL.User != nil {
		return nil, fmt.Errorf("webhook URL must not contain user credentials")
	}

	return parsedURL, nil
}

// ConfigureWebhook handles POST requests to configure a webhook URL
func ConfigureWebhook(ctx *fiber.Ctx) error {
	// Parse the JSON request body
	var req webhookRequest
	if err := ctx.BodyParser(&req); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "Invalid JSON format",
		})
	}

	// Validate that webhook_url is provided
	if req.WebhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "webhook_url is required",
		})
	}

	// Validate URL format and check for SSRF vulnerabilities
	_, err := validateURL(req.WebhookURL)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   err.Error(),
		})
	}

	// Create a custom HTTP client with timeout and security settings
	client := &http.Client{
		Timeout: 3 * time.Second,
		// Disable following redirects to prevent SSRF via redirects
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			return http.ErrUseLastResponse
		},
	}

	// Prepare test payload
	testPayload := webhookTestPayload{
		Message: "Webhook configuration test",
	}
	_, err = json.Marshal(testPayload)
	if err != nil {
		return ctx.Status(fiber.StatusInternalServerError).JSON(fiber.Map{
			"success": false,
			"error":   "Failed to create test payload",
		})
	}

	// Send test request to webhook URL using GET method as specified
	reqHTTP, err := http.NewRequest("GET", req.WebhookURL, nil)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   fmt.Sprintf("Failed to create test request: %v", err),
		})
	}

	// Set headers to prevent request smuggling and other attacks
	reqHTTP.Header.Set("User-Agent", "Webhook-Validator/1.0")
	reqHTTP.Header.Set("Accept", "application/json")

	resp, err := client.Do(reqHTTP)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   fmt.Sprintf("Failed to send test request to webhook URL: %v", err),
		})
	}
	defer resp.Body.Close()

	// Check if the webhook responded successfully (2xx status)
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   fmt.Sprintf("Webhook URL returned non-success status: %d", resp.StatusCode),
		})
	}

	// Save the configuration
	// db.SaveWebhookURL(req.WebhookURL) // Assume db is a predefined database instance

	// Return success response
	return ctx.Status(fiber.StatusOK).JSON(fiber.Map{
		"success": true,
		"message": "Webhook configured successfully",
	})
}

