package main

import (
	"encoding/json"
	"net/http"
	"time"

	"github.com/gofiber/fiber/v2"
)

// WebhookConfig represents the webhook configuration payload
type WebhookConfig struct {
	WebhookURL string `json:"webhook_url"`
}

// ConfigureWebhook handles POST requests to configure a webhook URL.
// It validates the URL by sending a GET test request with a 3-second timeout,
// then saves the configuration and returns the result.
func ConfigureWebhook(ctx *fiber.Ctx) error {
	var config WebhookConfig

	// Parse the JSON body
	if err := ctx.BodyParser(&config); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"message": "Invalid request body",
			"error":   err.Error(),
		})
	}

	// Validate that webhook_url is not empty
	if config.WebhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"message": "webhook_url is required",
		})
	}

	// Create an HTTP client with a 3-second timeout
	client := &http.Client{
		Timeout: 3 * time.Second,
	}

	// Send a GET test request to the webhook URL
	resp, err := client.Get(config.WebhookURL)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"message": "Failed to reach webhook URL",
			"error":   err.Error(),
		})
	}
	defer resp.Body.Close()

	// Check if the response status code indicates success
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"message": "Webhook URL returned non-success status",
			"status_code": resp.StatusCode,
		})
	}

	// Save the configuration (in-memory storage for this example)
	savedConfig = config

	return ctx.Status(fiber.StatusOK).JSON(fiber.Map{
		"success": true,
		"message": "Webhook configured successfully",
		"webhook_url": config.WebhookURL,
	})
}

// In-memory storage for the webhook configuration
var savedConfig WebhookConfig

func main() {
	app := fiber.New()

	// Register the webhook configuration endpoint
	app.Post("/configure-webhook", ConfigureWebhook)

	// Optional: endpoint to retrieve the saved configuration
	app.Get("/webhook-config", func(ctx *fiber.Ctx) error {
		if savedConfig.WebhookURL == "" {
			return ctx.Status(fiber.StatusNotFound).JSON(fiber.Map{
				"success": false,
				"message": "No webhook configured",
			})
		}
		return ctx.JSON(fiber.Map{
			"success": true,
			"webhook_url": savedConfig.WebhookURL,
		})
	})

	// Start the server
	app.Listen(":3000")
}

