	return ctx.JSON(Response{
		Success: true,
		Message: "Webhook configured successfully",
	})
}

// isPrivateIP checks if an IP address is private or reserved
func isPrivateIP(ip net.IP) bool {
	if ip == nil {
		return true
	}

	// Check for loopback
	if ip.IsLoopback() {
		return true
	}

	// Check for private networks
	if ip.IsPrivate() {
		return true
	}

	// Check for link-local
	if ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() {
		return true
	}

	// Check for unspecified (0.0.0.0 or ::)
	if ip.IsUnspecified() {
		return true
	}

	// Check for multicast
	if ip.IsMulticast() {
		return true
	}

	// Check for IPv4-mapped IPv6 addresses that map to private IPv4
	if v4 := ip.To4(); v4 != nil {
		return isPrivateIPv4(v4)
	}

	// Check for unique local IPv6 (fc00::/7)
	if len(ip) == net.IPv6len && ip[0]&0xfe == 0xfc {
		return true
	}

	return false
}

// isPrivateIPv4 checks if an IPv4 address is private or reserved
func isPrivateIPv4(ip net.IP) bool {
	if ip == nil {
		return true
	}

	// 10.0.0.0/8
	if ip[0] == 10 {
		return true
	}

	// 172.16.0.0/12
	if ip[0] == 172 && ip[1] >= 16 && ip[1] <= 31 {
		return true
	}

	// 192.168.0.0/16
	if ip[0] == 192 && ip[1] == 168 {
		return true
	}

	// 127.0.0.0/8 (loopback)
	if ip[0] == 127 {
		return true
	}

	// 169.254.0.0/16 (link-local)
	if ip[0] == 169 && ip[1] == 254 {
		return true
	}

	// 0.0.0.0/8 (current network)
	if ip[0] == 0 {
		return true
	}

	// 100.64.0.0/10 (shared address space / carrier-grade NAT)
	if ip[0] == 100 && ip[1] >= 64 && ip[1] <= 127 {
		return true
	}

	// 224.0.0.0/4 (multicast)
	if ip[0] >= 224 && ip[0] <= 239 {
		return true
	}

	// 240.0.0.0/4 (reserved)
	if ip[0] >= 240 {
		return true
	}

	return false
}

// validateWebhookURL sends a test GET request to the webhook URL with a 3-second timeout
func validateWebhookURL(rawURL string) error {
	// Parse the URL
	parsedURL, err := url.Parse(rawURL)
	if err != nil {
		return fmt.Errorf("invalid URL: %w", err)
	}

	// Block dangerous protocols
	scheme := strings.ToLower(parsedURL.Scheme)
	if scheme != "http" && scheme != "https" {
		return fmt.Errorf("unsupported protocol: %s", scheme)
	}

	// Resolve the hostname to IP addresses
	host := parsedURL.Hostname()
	if host == "" {
		return fmt.Errorf("invalid URL: missing host")
	}

	// Check if host is a raw IP address
	ip := net.ParseIP(host)
	if ip != nil {
		// Direct IP address - check if it's private
		if isPrivateIP(ip) {
			return fmt.Errorf("requests to private/internal IP addresses are not allowed")
		}
	} else {
		// Hostname - resolve and check all IPs
		ips, err := net.LookupIP(host)
		if err != nil {
			return fmt.Errorf("failed to resolve hostname: %w", err)
		}

		for _, resolvedIP := range ips {
			if isPrivateIP(resolvedIP) {
				return fmt.Errorf("hostname resolves to a private/internal IP address")
			}
		}
	}

	// Create a custom dialer that uses the already-resolved IP to prevent DNS rebinding
	dialer := &net.Dialer{
		Timeout:   3 * time.Second,
		KeepAlive: 3 * time.Second,
	}

	// Custom transport with DNS rebinding protection
	transport := &http.Transport{
		DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
			// Extract host and port from addr
			host, port, err := net.SplitHostPort(addr)
			if err != nil {
				return nil, err
			}

			// If the host is the same as our validated host, use the pre-resolved IPs
			if host == parsedURL.Hostname() {
				// Re-resolve to ensure consistency
				resolvedIPs, err := net.LookupIP(host)
				if err != nil {
					return nil, err
				}

				// Check all resolved IPs again for safety
				for _, resolvedIP := range resolvedIPs {
					if isPrivateIP(resolvedIP) {
						return nil, fmt.Errorf("hostname resolves to a private/internal IP address")
					}
				}

				// Use the first valid public IP
				for _, resolvedIP := range resolvedIPs {
					// Prefer IPv4
					if v4 := resolvedIP.To4(); v4 != nil {
						return dialer.DialContext(ctx, network, net.JoinHostPort(v4.String(), port))
					}
				}
				// Fallback to first IP
				if len(resolvedIPs) > 0 {
					return dialer.DialContext(ctx, network, net.JoinHostPort(resolvedIPs[0].String(), port))
				}
			}

			// For any other host, resolve and validate
			resolvedIPs, err := net.LookupIP(host)
			if err != nil {
				return nil, err
			}

			for _, resolvedIP := range resolvedIPs {
				if isPrivateIP(resolvedIP) {
					return nil, fmt.Errorf("hostname resolves to a private/internal IP address")
				}
			}

			return dialer.DialContext(ctx, network, addr)
		},
		DisableKeepAlives: true,
	}

	client := &http.Client{
		Timeout:   3 * time.Second,
		Transport: transport,
		// Do not follow redirects to prevent SSRF via redirect
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			if len(via) >= 10 {
				return fmt.Errorf("too many redirects")
			}

			// Validate the redirect URL
			redirectURL := req.URL.String()
			parsedRedirect, err := url.Parse(redirectURL)
			if err != nil {
				return fmt.Errorf("invalid redirect URL: %w", err)
			}

			// Check protocol
			redirectScheme := strings.ToLower(parsedRedirect.Scheme)
			if redirectScheme != "http" && redirectScheme != "https" {
				return fmt.Errorf("redirect to unsupported protocol: %s", redirectScheme)
			}

			// Check host
			redirectHost := parsedRedirect.Hostname()
			redirectIP := net.ParseIP(redirectHost)
			if redirectIP != nil {
				if isPrivateIP(redirectIP) {
					return fmt.Errorf("redirect to private/internal IP address is not allowed")
				}
			} else {
				redirectIPs, err := net.LookupIP(redirectHost)
				if err != nil {
					return fmt.Errorf("failed to resolve redirect hostname: %w", err)
				}
				for _, ip := range redirectIPs {
					if isPrivateIP(ip) {
						return fmt.Errorf("redirect hostname resolves to a private/internal IP address")
					}
				}
			}

			return nil
		},
	}

	resp, err := client.Get(rawURL)
	if err != nil {
		return fmt.Errorf("failed to reach webhook URL: %w", err)
	}
	defer resp.Body.Close()

	// Consider any 2xx status code as successful
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return fmt.Errorf("webhook URL returned status code %d", resp.StatusCode)
	}

	return nil
}

